// Set uses given function f to mock the watches.Watch method
func (mmWatch *mWatchesMockWatch) Set(f func(ctx context.Context, userID string, plate string) (err error)) *WatchesMock {
	if mmWatch.defaultExpectation != nil {
		mmWatch.mock.t.Fatalf("Default expectation is already set for the watches.Watch method")
	}

	if len(mmWatch.expectations) > 0 {
		mmWatch.mock.t.Fatalf("Some expectations are already set for the watches.Watch method")
	}

	mmWatch.mock.funcWatch = f
	mmWatch.mock.funcWatchOrigin = minimock.CallerInfo(1)
	return mmWatch.mock
}

// When sets expectation for the watches.Watch which will trigger the result defined by the following
// Then helper
func (mmWatch *mWatchesMockWatch) When(ctx context.Context, userID string, plate string) *WatchesMockWatchExpectation {
	if mmWatch.mock.funcWatch != nil {
		mmWatch.mock.t.Fatalf("WatchesMock.Watch mock is already set by Set")
	}

	expectation := &WatchesMockWatchExpectation{
		mock:               mmWatch.mock,
		params:             &WatchesMockWatchParams{ctx, userID, plate},
		expectationOrigins: WatchesMockWatchExpectationOrigins{origin: minimock.CallerInfo(1)},
	}
	mmWatch.expectations = append(mmWatch.expectations, expectation)
	return expectation
}

// Then sets up watches.Watch return parameters for the expectation previously defined by the When method
func (e *WatchesMockWatchExpectation) Then(err error) *WatchesMock {
	e.results = &WatchesMockWatchResults{err}
	return e.mock
}

// Times sets number of times watches.Watch should be invoked
func (mmWatch *mWatchesMockWatch) Times(n uint64) *mWatchesMockWatch {
	if n == 0 {
		mmWatch.mock.t.Fatalf("Times of WatchesMock.Watch mock can not be zero")
	}
	mm_atomic.StoreUint64(&mmWatch.expectedInvocations, n)
	mmWatch.expectedInvocationsOrigin = minimock.CallerInfo(1)
	return mmWatch
}

func (mmWatch *mWatchesMockWatch) invocationsDone() bool {
	if len(mmWatch.expectations) == 0 && mmWatch.defaultExpectation == nil && mmWatch.mock.funcWatch == nil {
		return true
	}

	totalInvocations := mm_atomic.LoadUint64(&mmWatch.mock.afterWatchCounter)
	expectedInvocations := mm_atomic.LoadUint64(&mmWatch.expectedInvocations)

	return totalInvocations > 0 && (expectedInvocations == 0 || expectedInvocations == totalInvocations)
}

// Watch implements mm_implementation.watches
func (mmWatch *WatchesMock) Watch(ctx context.Context, userID string, plate string) (err error) {
	mm_atomic.AddUint64(&mmWatch.beforeWatchCounter, 1)
	defer mm_atomic.AddUint64(&mmWatch.afterWatchCounter, 1)

	mmWatch.t.Helper()

	if mmWatch.inspectFuncWatch != nil {
		mmWatch.inspectFuncWatch(ctx, userID, plate)
	}

	mm_params := WatchesMockWatchParams{ctx, userID, plate}

	// Record call args
	mmWatch.WatchMock.mutex.Lock()
	mmWatch.WatchMock.callArgs = append(mmWatch.WatchMock.callArgs, &mm_params)
	mmWatch.WatchMock.mutex.Unlock()

	for _, e := range mmWatch.WatchMock.expectations {
		if minimock.Equal(*e.params, mm_params) {
			mm_atomic.AddUint64(&e.Counter, 1)
			return e.results.err
		}
	}

	if mmWatch.WatchMock.defaultExpectation != nil {
		mm_atomic.AddUint64(&mmWatch.WatchMock.defaultExpectation.Counter, 1)
		mm_want := mmWatch.WatchMock.defaultExpectation.params
		mm_want_ptrs := mmWatch.WatchMock.defaultExpectation.paramPtrs

		mm_got := WatchesMockWatchParams{ctx, userID, plate}

		if mm_want_ptrs != nil {

			if mm_want_ptrs.ctx != nil && !minimock.Equal(*mm_want_ptrs.ctx, mm_got.ctx) {
				mmWatch.t.Errorf("WatchesMock.Watch got unexpected parameter ctx, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmWatch.WatchMock.defaultExpectation.expectationOrigins.originCtx, *mm_want_ptrs.ctx, mm_got.ctx, minimock.Diff(*mm_want_ptrs.ctx, mm_got.ctx))
			}

			if mm_want_ptrs.userID != nil && !minimock.Equal(*mm_want_ptrs.userID, mm_got.userID) {
				mmWatch.t.Errorf("WatchesMock.Watch got unexpected parameter userID, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmWatch.WatchMock.defaultExpectation.expectationOrigins.originUserID, *mm_want_ptrs.userID, mm_got.userID, minimock.Diff(*mm_want_ptrs.userID, mm_got.userID))
			}

			if mm_want_ptrs.plate != nil && !minimock.Equal(*mm_want_ptrs.plate, mm_got.plate) {
				mmWatch.t.Errorf("WatchesMock.Watch got unexpected parameter plate, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmWatch.WatchMock.defaultExpectation.expectationOrigins.originPlate, *mm_want_ptrs.plate, mm_got.plate, minimock.Diff(*mm_want_ptrs.plate, mm_got.plate))
			}

		} else if mm_want != nil && !minimock.Equal(*mm_want, mm_got) {
			mmWatch.t.Errorf("WatchesMock.Watch got unexpected parameters, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
				mmWatch.WatchMock.defaultExpectation.expectationOrigins.origin, *mm_want, mm_got, minimock.Diff(*mm_want, mm_got))
		}

		mm_results := mmWatch.WatchMock.defaultExpectation.results
		if mm_results == nil {
			mmWatch.t.Fatal("No results are set for the WatchesMock.Watch")
		}
		return (*mm_results).err
	}
	if mmWatch.funcWatch != nil {
		return mmWatch.funcWatch(ctx, userID, plate)
	}
	mmWatch.t.Fatalf("Unexpected call to WatchesMock.Watch. %v %v %v", ctx, userID, plate)
	return
}

// WatchAfterCounter returns a count of finished WatchesMock.Watch invocations
func (mmWatch *WatchesMock) WatchAfterCounter() uint64 {
	return mm_atomic.LoadUint64(&mmWatch.afterWatchCounter)
}

// WatchBeforeCounter returns a count of WatchesMock.Watch invocations
func (mmWatch *WatchesMock) WatchBeforeCounter() uint64 {
	return mm_atomic.LoadUint64(&mmWatch.beforeWatchCounter)
}

// Calls returns a list of arguments used in each call to WatchesMock.Watch.
// The list is in the same order as the calls were made (i.e. recent calls have a higher index)
func (mmWatch *mWatchesMockWatch) Calls() []*WatchesMockWatchParams {
	mmWatch.mutex.RLock()

	argCopy := make([]*WatchesMockWatchParams, len(mmWatch.callArgs))
	copy(argCopy, mmWatch.callArgs)

	mmWatch.mutex.RUnlock()

	return argCopy
}

// MinimockWatchDone returns true if the count of the Watch invocations corresponds
// the number of defined expectations
func (m *WatchesMock) MinimockWatchDone() bool {
	if m.WatchMock.optional {
		// Optional methods provide '0 or more' call count restriction.
		return true
	}

	for _, e := range m.WatchMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			return false
		}
	}

	return m.WatchMock.invocationsDone()
}

// MinimockWatchInspect logs each unmet expectation
func (m *WatchesMock) MinimockWatchInspect() {
	for _, e := range m.WatchMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			m.t.Errorf("Expected call to WatchesMock.Watch at\n%s with params: %#v", e.expectationOrigins.origin, *e.params)
		}
	}

	afterWatchCounter := mm_atomic.LoadUint64(&m.afterWatchCounter)
	// if default expectation was set then invocations count should be greater than zero
	if m.WatchMock.defaultExpectation != nil && afterWatchCounter < 1 {
		if m.WatchMock.defaultExpectation.params == nil {
			m.t.Errorf("Expected call to WatchesMock.Watch at\n%s", m.WatchMock.defaultExpectation.returnOrigin)
		} else {
			m.t.Errorf("Expected call to WatchesMock.Watch at\n%s with params: %#v", m.WatchMock.defaultExpectation.expectationOrigins.origin, *m.WatchMock.defaultExpectation.params)
		}
	}
	// if func was set then invocations count should be greater than zero
	if m.funcWatch != nil && afterWatchCounter < 1 {
		m.t.Errorf("Expected call to WatchesMock.Watch at\n%s", m.funcWatchOrigin)
	}

	if !m.WatchMock.invocationsDone() && afterWatchCounter > 0 {
		m.t.Errorf("Expected %d calls to WatchesMock.Watch at\n%s but found %d calls",
			mm_atomic.LoadUint64(&m.WatchMock.expectedInvocations), m.WatchMock.expectedInvocationsOrigin, afterWatchCounter)
	}
}

// MinimockFinish checks that all mocked methods have been called the expected number of times
func (m *WatchesMock) MinimockFinish() {
	m.finishOnce.Do(func() {
		if !m.minimockDone() {
			m.MinimockListInspect()

			m.MinimockMarkSeenInspect()

			m.MinimockUnwatchInspect()

			m.MinimockWatchInspect()
		}
	})
}

// MinimockWait waits for all mocked methods to be called the expected number of times
func (m *WatchesMock) MinimockWait(timeout mm_time.Duration) {
	timeoutCh := mm_time.After(timeout)
	for {
		if m.minimockDone() {
			return
		}
		select {
		case <-timeoutCh:
			m.MinimockFinish()
			return
		case <-mm_time.After(10 * mm_time.Millisecond):
		}
	}
}

func (m *WatchesMock) minimockDone() bool {
	done := true
	return done &&
		m.MinimockListDone() &&
		m.MinimockMarkSeenDone() &&
		m.MinimockUnwatchDone() &&
		m.MinimockWatchDone()
}
